"""it — prophets_c."""

T = {
"prophets_151": ("Da che cosa fu proibito ad Adamo e a sua moglie di avvicinarsi nel Giardino?", ["Da un albero", "Da un fiume", "Da una porta", "Da una montagna"], "Allah permise loro di mangiare a volontà, tranne avvicinarsi a un solo albero."),
"prophets_152": ("Secondo il Corano, che cosa ricevette Adamo dal suo Signore dopo il suo errore?", ["Delle parole (di pentimento), e Allah accolse il suo pentimento", "Ricchezza", "Un regno", "Un libro"], "«Adamo ricevette parole dal suo Signore, ed Egli accolse il suo pentimento»."),
"prophets_153": ("A chi paragona il Corano 'Isa quanto alla sua creazione?", ["Ad Adamo, creato dalla terra", "A Nuh (Noè)", "A Ibrahim (Abramo)", "A Yahya (Giovanni)"], "«In verità, l'esempio di 'Isa presso Allah è come quello di Adamo: lo creò dalla terra, poi gli disse “Sii!” ed egli fu»."),
"prophets_154": ("Di quale profeta dice il Corano che era veritiero e che Allah lo elevò a un rango sublime?", ["Idris (Enoch)", "Ilyas (Elia)", "Dhul-Kifl", "Al-Yasa' (Eliseo)"], "«E ricorda Idris nel Libro: era veritiero, un profeta; e lo elevammo a un rango sublime»."),
"prophets_155": ("Che cosa disse Nuh quando i suoi salirono sull'arca?", ["«Nel nome di Allah sia il suo corso e il suo ormeggio»", "«Non temete il mare»", "«Prendete le provviste»", "«Aspettate la notte»"], "«Salite in essa: nel nome di Allah sia il suo corso e il suo ormeggio»."),
"prophets_156": ("Nella sura Nuh, che cosa chiese il profeta Nuh al suo Signore riguardo ai miscredenti?", ["Di non lasciarne sulla terra nemmeno uno", "Di renderli ricchi", "Di concedere loro un altro anno", "Di esiliarli"], "«Signore, non lasciare sulla terra alcun abitante fra i miscredenti»."),
"prophets_157": ("Quanti esemplari di ogni specie doveva Nuh imbarcare sull'arca?", ["Una coppia", "Tre", "Dieci", "Uno solo"], "Allah gli ordinò di caricarvi una coppia di ogni specie, insieme alla sua famiglia."),
"prophets_158": ("Hud ricordò agli 'Ad che Allah li aveva resi successori dopo quale popolo?", ["Il popolo di Nuh (Noè)", "Il popolo di Lut (Lot)", "Il popolo di Musa (Mosè)", "Il popolo di Saba"], "«Ricordate quando vi fece successori dopo il popolo di Nuh e vi accrebbe nella statura»."),
"prophets_159": ("Con che cosa fu distrutto il popolo degli 'Ad, secondo la sura Al-Haqqa?", ["Con un vento gelido e ululante", "Con un diluvio", "Con un terremoto", "Con una piaga di locuste"], "«Quanto agli 'Ad, furono distrutti da un vento gelido e impetuoso»."),
"prophets_160": ("Che cosa rimproverò Hud al suo popolo, che costruiva su ogni altura?", ["Costruire per vanità e sperare di vivere in eterno", "Coltivare la terra", "Commerciare lontano", "Viaggiare di notte"], "«Costruite su ogni altura un monumento per divertimento? E vi prendete castelli come se doveste vivere in eterno?»"),
"prophets_161": ("Che cosa faceva Thamud con le montagne, secondo il Corano?", ["Vi scavava le proprie case", "Vi nascondeva l'oro", "Vi pascolava le greggi", "Le evitava"], "«Prendete castelli nelle sue pianure e scavate case nelle montagne»."),
"prophets_162": ("Secondo la sura Al-Qamar, la cammella fu inviata a Thamud come che cosa?", ["Come prova per loro", "Come ricompensa", "Come dono del loro re", "Come gregge da vendere"], "«Manderemo loro la cammella come prova: osservali e sii paziente»."),
"prophets_163": ("Che cosa colpì Thamud dopo che uccisero la cammella?", ["Il terremoto (ar-rajfa)", "Il diluvio", "Il vento gelido", "La carestia"], "«Li colse il terremoto, e al mattino giacevano nelle loro dimore»."),
"prophets_164": ("Quale profeta fu inviato al popolo che commetteva la grande turpitudine, dicendo «Non temerete Allah?»", ["Lut (Lot)", "Salih", "Hud", "Shu'ayb"], "«Quando il loro fratello Lut disse loro: “Non temerete Allah?”»"),
"prophets_165": ("Che cosa fu ordinato a Lut nella notte del castigo?", ["Partire di notte con la sua famiglia e non voltarsi indietro", "Radunare il suo popolo", "Attendere l'alba", "Nascondersi sul monte"], "«Parti dunque con la tua famiglia in un momento della notte, e nessuno di voi si volti indietro»."),
"prophets_166": ("Quale profeta fu inviato al popolo di Madyan, che frodava sulla misura e sul peso?", ["Shu'ayb", "Lut (Lot)", "Hud", "Ilyas (Elia)"], "Shu'ayb ordinò loro di dare piena misura e giusto peso, e di non spargere corruzione sulla terra."),
"prophets_167": ("Che cosa disse Shu'ayb al suo popolo su ciò che davvero voleva?", ["«Non voglio che la riforma, per quanto mi è possibile»", "«Voglio solo ricchezza»", "«Voglio governare»", "«Voglio andarmene»"], "«Non voglio che la riforma, per quanto mi è possibile. E il mio successo dipende solo da Allah»."),
"prophets_168": ("Dopo che Allah mise alla prova Ibrahim con ordini che egli adempì, che cosa gli disse?", ["«Farò di te una guida (imam) per gli uomini»", "«Ti darò un regno»", "«Ti renderò ricco»", "«Ti farò re di Babilonia»"], "«Farò di te una guida per gli uomini». Ibrahim chiese: «E della mia discendenza?»"),
"prophets_169": ("Come ridusse Ibrahim al silenzio il re che pretendeva di dare la vita e la morte?", ["«Allah fa sorgere il sole da oriente: fallo sorgere tu da occidente»", "«Fa' cadere la pioggia»", "«Sposta quella montagna»", "«Conta le stelle»"], "«Allah fa sorgere il sole da oriente; fallo sorgere tu da occidente». E il miscredente rimase confuso."),
"prophets_170": ("Che cosa fu ordinato a Ibrahim di proclamare agli uomini riguardo alla Casa Sacra?", ["Il pellegrinaggio: verranno a piedi e su ogni cavalcatura", "Il commercio", "La guerra", "Il silenzio"], "«E proclama agli uomini il pellegrinaggio: verranno a te a piedi e su ogni cammella smagrita»."),
"prophets_171": ("Che cosa offrì Ibrahim ai suoi ospiti onorati, che non lo toccarono?", ["Un vitello grasso arrostito", "Pane e acqua", "Datteri", "Latte"], "Andò dai suoi e portò un vitello grasso; vedendo che le loro mani non lo toccavano, provò timore."),
"prophets_172": ("Di chi dice il Corano che è «un bell'esempio» (uswa hasana) per i credenti, insieme a chi era con lui?", ["Ibrahim (Abramo)", "Nuh (Noè)", "Musa (Mosè)", "Dawud (Davide)"], "«Avete avuto un bell'esempio in Ibrahim e in coloro che erano con lui»."),
"prophets_173": ("Nella sura Ibrahim, che cosa chiese Ibrahim per la città della Mecca?", ["Che fosse sicura, e che lui e i suoi figli fossero preservati dall'adorare gli idoli", "Che diventasse un grande mercato", "Che avesse palazzi", "Che restasse deserta"], "«Signore, rendi sicura questa città e preserva me e i miei figli dall'adorare gli idoli»."),
"prophets_174": ("Che cosa disse Ibrahim lasciando il suo popolo?", ["«Vado verso il mio Signore: Egli mi guiderà»", "«Vado a cercar fortuna»", "«Tornerò a combatterli»", "«Vado in Egitto»"], "«In verità vado verso il mio Signore: Egli mi guiderà»."),
"prophets_175": ("Di quale profeta dice il Corano che era «fedele alla sua promessa» e ordinava ai suoi la preghiera e la zakat?", ["Isma'il (Ismaele)", "Ishaq (Isacco)", "Ya'qub (Giacobbe)", "Yusuf (Giuseppe)"], "«Era fedele alla sua promessa; era un messaggero e un profeta. Ordinava alla sua famiglia la preghiera e la zakat»."),
"prophets_176": ("Che cosa consigliò Ya'qub a Yusuf dopo il suo sogno?", ["Di non raccontarlo ai suoi fratelli", "Di raccontarlo a tutti", "Di scriverlo", "Di dimenticarlo"], "«O figlio mio, non raccontare la tua visione ai tuoi fratelli, ché non ordiscano contro di te qualche trama»."),
"prophets_177": ("Quale indizio stabilì l'innocenza di Yusuf davanti al padrone di casa?", ["La sua tunica strappata da dietro", "Un testimone nascosto", "Una lettera", "Un giuramento"], "Se la tunica era strappata di dietro, ella ha mentito ed egli è tra i veritieri."),
"prophets_178": ("Che cosa fecero le donne della città vedendo Yusuf?", ["Si tagliarono le mani per l'ammirazione", "Fuggirono", "Tacquero", "Risero"], "«Quando lo videro, lo esaltarono e si tagliarono le mani, dicendo: “Questo non è un essere umano; non è che un angelo nobile!”»"),
"prophets_179": ("Che cosa insegnò Yusuf ai suoi due compagni di prigione prima di interpretare i loro sogni?", ["L'unicità di Allah, e che il giudizio appartiene solo a Lui", "La medicina", "Il calcolo dei raccolti", "La poesia"], "«Sono forse meglio signori diversi, o Allah, l'Unico, il Dominatore? … Il giudizio appartiene solo ad Allah»."),
"prophets_180": ("Che cosa disse il re d'Egitto a Yusuf dopo aver parlato con lui?", ["«Da oggi sei presso di noi in posizione autorevole e degno di fiducia»", "«Torna in prigione»", "«Lascia l'Egitto»", "«Ti do mia figlia»"], "«Quando gli ebbe parlato, disse: “Da oggi sei presso di noi in posizione autorevole e degno di fiducia”»."),
"prophets_181": ("Come trattenne Yusuf suo fratello presso di sé?", ["La coppa del re fu trovata nel bagaglio di suo fratello", "Lo comprò", "Lo imprigionò senza motivo", "Lo nominò ministro"], "«Così ispirammo questo stratagemma a Yusuf»: la coppa uscì dal sacco di suo fratello."),
"prophets_182": ("Che cosa disse Yusuf ai suoi fratelli quando riconobbero la loro colpa?", ["«Oggi non ci sono rimproveri per voi»", "«Sarete puniti»", "«Andatevene e non tornate»", "«Vi ho dimenticati»"], "«Oggi non ci sono rimproveri per voi. Che Allah vi perdoni: Egli è il più misericordioso dei misericordiosi»."),
"prophets_183": ("Che cosa disse Ya'qub ai suoi figli sulla disperazione?", ["«Non disperate della misericordia di Allah»", "«Non partite più»", "«Non parlate con nessuno»", "«Non scrivete nulla»"], "«E non disperate del soccorso di Allah: solo i miscredenti disperano del soccorso di Allah»."),
"prophets_184": ("Quale invocazione fece Yusuf alla fine della sua storia?", ["Morire sottomesso (musulmano) ed essere riunito ai giusti", "Regnare su tutto l'Egitto", "Tornare a Canaan", "Vivere a lungo"], "«Fammi morire sottomesso e riuniscimi ai giusti»."),
"prophets_185": ("Come si rivolse Ayyub al suo Signore nella prova?", ["«Il male mi ha colpito, e Tu sei il più Misericordioso»", "«Perché io?»", "«Rendimi la mia ricchezza»", "«Distruggi i miei nemici»"], "«E ricorda il Nostro servo Ayyub, quando invocò il suo Signore: “Satana mi ha colpito con affanno e tormento”»."),
"prophets_186": ("Che cosa restituì Allah ad Ayyub dopo la prova, secondo la sura Sad?", ["La sua famiglia, e altrettanti con loro", "Un regno", "Una nave", "Una mandria di cammelli"], "«E gli restituimmo la sua famiglia e altrettanti con loro, come misericordia da parte Nostra e monito per coloro che hanno intelletto»."),
"prophets_187": ("Secondo la sura As-Saffat, che cosa salvò Yunus dal restare nel ventre del pesce?", ["Che era di quelli che glorificano Allah", "La sua forza", "Una nave di passaggio", "Un vento favorevole"], "«Se non fosse stato uno di quelli che glorificano, sarebbe rimasto nel suo ventre fino al Giorno della Resurrezione»."),
"prophets_188": ("Quale popolo, secondo il Corano, credette prima che il castigo lo raggiungesse, e ne trasse beneficio?", ["Il popolo di Yunus (Giona)", "Il popolo di Nuh", "Il popolo di Lut", "Il popolo di Hud"], "«Non c'è stata città che abbia creduto e a cui la fede abbia giovato, se non il popolo di Yunus»."),
"prophets_189": ("Come chiama il Corano Yunus quando ordina al Profeta ﷺ di non essere come lui nell'impazienza?", ["«Il compagno del pesce» (sahib al-hut)", "«L'uomo del bastone»", "«L'uomo della montagna»", "«L'uomo del pozzo»"], "«E non essere come il compagno del pesce, quando invocò pieno di angoscia»."),
"prophets_190": ("Quale profeta rimproverò al suo popolo di invocare Ba'l e di abbandonare il migliore dei creatori?", ["Ilyas (Elia)", "Al-Yasa' (Eliseo)", "Yunus (Giona)", "Shu'ayb"], "«In verità Ilyas era tra i messaggeri… “Invocate Ba'l e abbandonate il migliore dei creatori?”»"),
"prophets_191": ("Accanto a Isma'il e Idris, quale profeta nomina il Corano tra i pazienti che Allah fece entrare nella Sua misericordia?", ["Dhul-Kifl", "Ilyas (Elia)", "Yunus (Giona)", "Al-Yasa' (Eliseo)"], "«E Isma'il, Idris e Dhul-Kifl: tutti erano tra i pazienti. E li facemmo entrare nella Nostra misericordia»."),
"prophets_192": ("Che cosa fece Allah per i Figli d'Israele davanti al mare, inseguiti dal Faraone?", ["Divise il mare e li salvò", "Fece scendere la notte", "Inviò navi", "Prosciugò il mare per sempre"], "«E quando dividemmo il mare per voi: vi salvammo e annegammo la gente del Faraone»."),
"prophets_193": ("Perché Musa chiese ad Allah di inviare Harun con lui?", ["Perché era più eloquente di lui", "Perché era più anziano", "Perché conosceva l'Egitto", "Perché sapeva scrivere"], "«E mio fratello Harun è più eloquente di me: mandalo dunque con me come sostegno che mi confermi»."),
"prophets_194": ("Come dovevano Musa e Harun parlare al Faraone?", ["Con parole gentili", "Con minacce", "Senza guardarlo", "Solo per iscritto"], "«E parlategli con parole gentili: forse ricorderà o temerà»."),
"prophets_195": ("Chi, nella famiglia del Faraone, difese Musa nascondendo la propria fede?", ["Un uomo credente della famiglia del Faraone", "Il sommo sacerdote", "Il comandante dell'esercito", "Il visir Haman"], "«E un uomo credente della famiglia del Faraone, che nascondeva la sua fede, disse: “Ucciderete un uomo perché dice: il mio Signore è Allah?”»"),
"prophets_196": ("Che cosa disse Harun al suo popolo durante l'assenza di Musa?", ["Che erano solo messi alla prova con il vitello, e dovevano seguirlo", "Di conservare il vitello", "Di partire per l'Egitto", "Di tacere"], "«O popolo mio, siete solo messi alla prova con esso. Il vostro Signore è il Compassionevole: seguitemi dunque»."),
"prophets_197": ("Che cosa disse la moglie del Faraone trovando il neonato Musa?", ["«Sarà gioia degli occhi per me e per te: non uccidetelo»", "«Riportatelo a sua madre»", "«Portatelo al fiume»", "«Vendetelo»"], "«E la moglie del Faraone disse: “Gioia degli occhi per me e per te. Non uccidetelo: forse ci sarà utile”»."),
"prophets_198": ("Come chiese Musa di seguire il servo sapiente (al-Khidr)?", ["«Posso seguirti, a condizione che tu mi insegni?»", "«Comandami e obbedirò»", "«Insegnami a pagamento»", "«Vieni con me»"], "«Posso seguirti, a condizione che tu mi insegni di ciò che ti è stato insegnato quanto a retta via?»"),
"prophets_199": ("In quale stato tornò Musa al suo popolo dopo aver visto il vitello?", ["Adirato e afflitto", "Gioioso", "Silenzioso", "Indifferente"], "«E quando Musa tornò al suo popolo, adirato e afflitto… gettò le Tavole»."),
"prophets_200": ("Quale messaggio doveva portare Musa al Faraone secondo la sura An-Nazi'at?", ["«Vuoi purificarti, e che io ti guidi verso il tuo Signore?»", "«Rendimi il mio popolo»", "«Costruiscimi un palazzo»", "«Lascia l'Egitto»"], "«Va' dal Faraone: ha davvero superato ogni limite. E digli: vuoi purificarti? E che io ti guidi al tuo Signore, affinché tu Lo tema?»"),
"prophets_201": ("Chi glorificava Allah insieme a Dawud, sera e mattina?", ["Le montagne e gli uccelli", "I fiumi", "Le stelle", "I venti"], "«Sottomettemmo le montagne a glorificare con lui, sera e mattina, e gli uccelli riuniti»."),
"prophets_202": ("Che cosa dice il Corano che Allah diede a Dawud, insieme a un regno saldo?", ["La saggezza e la parola decisiva", "Eserciti immensi", "Oro e argento", "Un palazzo d'avorio"], "«Consolidammo il suo regno e gli demmo la saggezza e la capacità di dirimere le controversie»."),
"prophets_203": ("Che cosa fu ordinato a Dawud nel fabbricare le cotte di maglia?", ["Di misurarne bene le maglie", "Di inciderci il suo nome", "Di dorarle", "Di venderle"], "«Fabbrica cotte di maglia complete e misurane bene le maglie»."),
"prophets_204": ("Che cosa dissero Dawud e Sulayman quando Allah diede loro la scienza?", ["«Lode ad Allah, che ci ha favoriti su molti dei Suoi servi credenti»", "«Siamo i migliori»", "«Nessuno ci eguaglia»", "«Ce lo siamo meritato»"], "«Lode ad Allah, che ci ha favoriti su molti dei Suoi servi credenti»."),
"prophets_205": ("Che cosa fece Sulayman udendo la formica avvertire i suoi?", ["Sorrise e chiese ad Allah di renderlo riconoscente", "Si adirò", "Deviò il suo esercito in silenzio", "Ordinò il silenzio"], "«Sorrise alle sue parole e disse: “Signore, permettimi di essere grato per la Tua grazia”»."),
"prophets_206": ("Quale notizia portò l'upupa a Sulayman?", ["Che una donna regnava su Saba e il suo popolo si prosternava al sole", "Che un esercito si avvicinava", "Che c'era siccità", "Che c'era un tesoro nascosto"], "«Vengo da Saba con una notizia certa: vi ho trovato una donna che regna su di loro… si prosternano al sole»."),
"prophets_207": ("Che cosa stupì la regina di Saba entrando nel palazzo di Sulayman?", ["Il pavimento di cristallo, che prese per acqua", "Un leone addomesticato", "Un giardino pensile", "Un trono d'oro"], "«Le fu detto: “Entra nel palazzo”. Vedendolo, lo credette acqua profonda e si scoprì le gambe. Egli disse: “È un palazzo lastricato di cristallo”»."),
"prophets_208": ("Di che cosa erano composti gli eserciti di Sulayman, secondo il Corano?", ["Di jinn, uomini e uccelli", "Solo di cavalieri", "Di marinai", "Solo di arcieri"], "«E furono riuniti per Sulayman i suoi eserciti di jinn, uomini e uccelli, disposti in ranghi»."),
"prophets_209": ("Come descrisse Zakariyya il suo stato invocando il suo Signore?", ["«Le mie ossa si sono infiacchite e il mio capo si è acceso di canizie»", "«Sono ricco e sazio»", "«Sono lontano dal mio popolo»", "«Sono in viaggio»"], "«Signore, le mie ossa si sono infiacchite e il mio capo si è acceso di canizie, e mai fui deluso nell'invocarTi»."),
"prophets_210": ("Quale segno fu dato a Zakariyya per la nascita di Yahya?", ["Non parlare agli uomini per tre giorni se non a gesti", "Una stella", "Pioggia fuori stagione", "Un sogno ripetuto"], "«Il tuo segno è che per tre giorni non parlerai agli uomini se non a gesti»."),
"prophets_211": ("Che cosa fu detto a Yahya riguardo al Libro?", ["«Prendi il Libro con forza»", "«Nascondi il Libro»", "«Copia il Libro»", "«Leggilo una volta»"], "«O Yahya, prendi il Libro con determinazione!» E gli demmo la saggezza mentre era ancora fanciullo."),
"prophets_212": ("Che cosa ordinarono gli angeli a Maryam dopo averle annunciato la sua elezione?", ["Di essere devota al suo Signore, di prosternarsi e di inchinarsi", "Di intraprendere un viaggio", "Di tacere per sempre", "Di insegnare nel Tempio"], "«O Maryam, sii devota al tuo Signore, prosternati e inchinati con coloro che si inchinano»."),
"prophets_213": ("Che cosa fu detto a Maryam di scuotere per mangiare, al momento del parto?", ["Il tronco della palma, perché cadessero datteri freschi", "Un ulivo", "Un fico", "Una vite"], "«E scuoti verso di te il tronco della palma: farà cadere su di te datteri freschi e maturi»."),
"prophets_214": ("Che cosa disse 'Isa nella culla riguardo a ciò che Allah gli aveva raccomandato?", ["La preghiera e la zakat finché avesse vissuto", "Il commercio", "Il silenzio", "Il viaggio"], "«E mi ha raccomandato la preghiera e la zakat finché avrò vita»."),
"prophets_215": ("Come descrive la sura Az-Zukhruf 'Isa figlio di Maryam?", ["Un servo che Allah ha colmato di grazia e ha reso esempio per i Figli d'Israele", "Un re d'Israele", "Un angelo disceso", "Uno scriba del Tempio"], "«Non era che un servo che colmammo di grazia e ponemmo a esempio per i Figli d'Israele»."),
"prophets_216": ("Che cosa risponderà 'Isa nel Giorno della Resurrezione quando Allah lo interrogherà?", ["«Gloria a Te! Non spetta a me dire ciò a cui non ho diritto»", "«Non ricordo»", "«Sono loro che hanno scritto»", "«Chiedi ai discepoli»"], "«Gloria a Te! Non spetta a me dire ciò a cui non ho diritto»."),
"prophets_217": ("Come descrive il Corano 'Isa figlio di Maryam?", ["Il messaggero di Allah, la Sua parola indirizzata a Maryam e uno spirito da Lui proveniente", "Un angelo inviato", "Un re giusto", "Uno scriba dotto"], "«Il Messia 'Isa figlio di Maryam non è che il messaggero di Allah e la Sua parola che indirizzò a Maryam, e uno spirito da Lui proveniente»."),
"prophets_218": ("Nella sura Ad-Duha, quali grazie ricorda Allah al Suo Profeta ﷺ?", ["Lo accolse orfano, lo guidò e lo arricchì", "Gli diede un regno", "Gli diede un esercito", "Gli diede un palazzo"], "«Non ti ha trovato orfano e ti ha dato rifugio? E non ti ha trovato smarrito e ti ha guidato? E non ti ha trovato povero e ti ha arricchito?»"),
"prophets_219": ("Quale promessa ripete due volte la sura Ash-Sharh?", ["«In verità, con la difficoltà viene la facilità»", "«La vittoria è vicina»", "«Il Paradiso è promesso»", "«I nemici periranno»"], "«In verità, con la difficoltà viene la facilità. In verità, con la difficoltà viene la facilità»."),
"prophets_220": ("Che cosa fu concesso al Profeta ﷺ nella sura Al-Kawthar, e che cosa gli fu ordinato in cambio?", ["Al-Kawthar; pregare il suo Signore e sacrificare", "Un esercito; combattere", "Un regno; governare", "Un tesoro; distribuirlo"], "«In verità ti abbiamo concesso al-Kawthar. Prega dunque il tuo Signore e sacrifica»."),
"prophets_221": ("Come descrive la sura At-Tawba il Messaggero ﷺ verso i credenti?", ["Sollecito per loro, dolce e misericordioso", "Duro e distante", "Ricco e potente", "Silenzioso e ritirato"], "«Vi è giunto un Messaggero scelto tra voi… sollecito per voi, dolce e misericordioso verso i credenti»."),
"prophets_222": ("Secondo il Corano, che cosa avrebbe allontanato la gente dal Profeta ﷺ, se fosse stato così?", ["Se fosse stato rude e duro di cuore", "Se fosse stato ricco", "Se fosse stato giovane", "Se fosse stato silenzioso"], "«Per misericordia di Allah fosti dolce con loro. Se fossi stato rude e duro di cuore, si sarebbero allontanati da te»."),
"prophets_223": ("Che cosa dice il Corano del Messaggero di Allah ﷺ per chi spera in Allah e nell'Ultimo Giorno?", ["È per loro un bell'esempio", "È un re", "È un giudice", "È una guida di carovane"], "«Avete nel Messaggero di Allah un bell'esempio, per chi spera in Allah e nell'Ultimo Giorno»."),
"prophets_224": ("A chi fu inviato il Profeta Muhammad ﷺ, secondo la sura Saba?", ["All'umanità intera", "Solo ai Quraysh", "Solo agli arabi", "Alla gente di Medina"], "«E non ti abbiamo inviato se non come annunciatore e ammonitore per tutta l'umanità»."),
"prophets_225": ("Quale versetto recitò il Profeta ﷺ mentre gli idoli attorno alla Ka'ba venivano rimossi?", ["«È giunta la verità ed è svanito il falso»", "«Ti abbiamo concesso una vittoria evidente»", "«Di': Egli è Allah, l'Unico»", "«Quando giunge il soccorso di Allah»"], "«E di': è giunta la verità ed è svanito il falso; in verità il falso è destinato a svanire»."),
"prophets_226": ("Che cosa dicono i credenti riguardo ai messaggeri di Allah, alla fine della sura Al-Baqara?", ["«Non facciamo differenza alcuna tra i Suoi messaggeri»", "«Seguiamo solo l'ultimo»", "«Ne preferiamo uno»", "«Li ignoriamo»"], "«Non facciamo differenza alcuna tra i Suoi messaggeri. E dissero: abbiamo udito e obbediamo»."),
"prophets_227": ("Quale messaggio comune portò ogni messaggero al suo popolo?", ["«Adorate Allah e allontanatevi dal Tāghūt»", "«Costruite templi»", "«Arricchitevi»", "«Scrivete libri»"], "«Inviammo a ogni comunità un messaggero: adorate Allah e allontanatevi dal Tāghūt»."),
"prophets_228": ("In quale lingua fu inviato ogni messaggero, secondo la sura Ibrahim?", ["Nella lingua del suo popolo, per spiegare loro", "Solo in arabo", "In ebraico", "In una lingua celeste"], "«E non inviammo alcun messaggero se non nella lingua del suo popolo, affinché spiegasse loro»."),
"prophets_229": ("Che cosa fu rivelato a ogni messaggero prima di Muhammad ﷺ, secondo la sura Al-Anbiya?", ["Che non c'è divinità all'infuori di Lui: adorateLo dunque", "Di costruire un santuario", "Di conquistare terre", "Di custodire il segreto"], "«E non inviammo prima di te alcun messaggero senza rivelargli: non c'è divinità all'infuori di Me, adorateMi dunque»."),
"prophets_230": ("Nella sura Al-An'am, quale gruppo di profeti è enumerato come la discendenza guidata di Ibrahim?", ["Dawud, Sulayman, Ayyub, Yusuf, Musa e Harun tra gli altri", "Solo Musa e 'Isa", "Solo Isma'il e Ishaq", "Solo Nuh e Hud"], "Il passo enumera una lunga stirpe di profeti che Allah guidò, e dice: «Così ricompensiamo coloro che fanno il bene»."),
"prophets_231": ("Che cosa dice il Corano dei messaggeri gli uni rispetto agli altri?", ["Allah ne ha favoriti alcuni rispetto ad altri", "Sono tutti di uguale rango", "Solo l'ultimo conta", "Si ignoravano a vicenda"], "«Tra questi messaggeri, ne abbiamo favoriti alcuni rispetto ad altri»."),
"prophets_232": ("Quale patto prese Allah dai profeti, secondo la sura Al 'Imran?", ["Credere nel Messaggero che sarebbe venuto a confermare quanto avevano, e sostenerlo", "Non lasciare mai il loro popolo", "Costruire ciascuno un tempio", "Scrivere ciascuno un libro"], "«Se vi giunge un Messaggero che conferma ciò che avete, dovrete credere in lui e sostenerlo»."),
"prophets_233": ("Quali profeti nomina il Corano dicendo che Allah prescrisse loro la stessa religione?", ["Nuh, Ibrahim, Musa e 'Isa, insieme a ciò che fu rivelato al Profeta ﷺ", "Solo Adamo e Idris", "Solo Dawud e Sulayman", "Solo Hud e Salih"], "«Ha stabilito per voi, in materia di religione, quanto raccomandò a Nuh, quello che ti abbiamo rivelato, e quello che raccomandammo a Ibrahim, a Musa e a 'Isa»."),
"prophets_234": ("Che cosa dice il Corano dei messaggeri di cui non racconta la storia?", ["Ve ne sono alcuni la cui storia Allah non ha raccontato al Profeta ﷺ", "Non esistono", "Sono tutti nominati", "Non hanno importanza"], "«Di alcuni ti abbiamo raccontato la storia, e di altri non te l'abbiamo raccontata»."),
"prophets_235": ("Tra chi scelse Allah tutti i Suoi messaggeri, secondo la sura Yusuf?", ["Tra uomini delle città, ai quali rivelava", "Tra gli angeli", "Tra i re", "Solo tra gli abitanti del deserto"], "«E non inviammo prima di te che uomini delle città, ai quali rivelavamo»."),
"prophets_236": ("Che cosa ricorda il Corano riguardo ai messaggeri smentiti prima di Muhammad ﷺ?", ["Furono pazienti finché giunse loro il Nostro soccorso", "Si arresero", "Si nascosero", "Cambiarono messaggio"], "«Già prima di te furono smentiti messaggeri, ma sopportarono con pazienza la smentita finché giunse loro il Nostro soccorso»."),
"prophets_237": ("Quali famiglie scelse Allah al di sopra dei mondi, secondo la sura Al 'Imran?", ["Adamo, Nuh, la famiglia di Ibrahim e la famiglia di 'Imran", "I re d'Egitto", "Le tribù di Medina", "La gente di Saba"], "«In verità Allah ha scelto Adamo, Nuh, la famiglia di Ibrahim e la famiglia di 'Imran al di sopra dei mondi»."),
"prophets_238": ("Quali grazie ricordò Musa al suo popolo invitandolo a entrare nella Terra Santa?", ["Che Allah aveva suscitato profeti tra loro e li aveva resi re", "Che aveva dato loro navi", "Che aveva dato loro oro", "Che aveva dato loro cavalli"], "«O popolo mio, ricordate la grazia di Allah su di voi: suscitò profeti tra voi e vi fece re»."),
"prophets_239": ("Come descrivevano la Torah e il Vangelo il Profeta illetterato, secondo il Corano?", ["Ordina il bene, vieta il male e li libera dai loro fardelli", "Porta ricchezza", "Governa con la forza", "Costruisce templi"], "«…il profeta illetterato che trovano menzionato nella Torah e nel Vangelo: ordina loro il bene e vieta il male… e li libera dal loro fardello»."),
"prophets_240": ("Su chi disse Nuh di appoggiarsi sfidando il suo popolo a tramare?", ["Su Allah, in cui riponeva la sua fiducia", "Sui suoi figli", "Sulla sua tribù", "Sulla sua nave"], "«In Allah ripongo la mia fiducia. Mettetevi d'accordo, voi e i vostri associati»."),
"prophets_241": ("Nell'invocazione di Ibrahim, a chi attribuisce la guarigione quando è malato?", ["Ad Allah soltanto", "Ai medici", "Alle piante", "Al tempo"], "«E quando sono malato, è Lui che mi guarisce», disse Ibrahim descrivendo il suo Signore."),
"prophets_242": ("Con che cosa fu riscattato il figlio di Ibrahim, secondo la sura As-Saffat?", ["Con un sacrificio immenso", "Con un riscatto d'oro", "Con una carovana", "Con un'intera mandria"], "«E lo riscattammo con un sacrificio immenso»."),
"prophets_243": ("In che cosa dichiarano di credere i credenti, nel versetto «Dite: crediamo in Allah…»?", ["In ciò che fu rivelato a Ibrahim, Isma'il, Ishaq, Ya'qub, Musa, 'Isa e ai profeti", "In un solo libro", "In un solo profeta", "Nelle proprie tradizioni"], "«Dite: crediamo in Allah e in quello che è stato fatto scendere su di noi, e in quello che è stato rivelato a Ibrahim, Isma'il, Ishaq, Ya'qub…»"),
"prophets_244": ("Perché Allah racconta al Profeta ﷺ le storie dei messaggeri?", ["Per rafforzare il suo cuore", "Per occuparlo", "Per insegnargli la storia", "Per distrarlo"], "«E tutto ciò che ti raccontiamo delle storie dei messaggeri è per rafforzare con esso il tuo cuore»."),
"prophets_245": ("Che cosa fu ordinato al Profeta ﷺ di dire di sé, alla fine della sura Al-Kahf?", ["«Non sono che un uomo come voi; mi è stato rivelato che il vostro Dio è un Dio unico»", "«Sono un re»", "«Sono un angelo»", "«Conosco l'invisibile»"], "«Di': non sono che un uomo come voi; mi è stato rivelato che il vostro Dio è un Dio unico»."),
"prophets_246": ("Come descrive la sura Al-Fath coloro che sono con il Messaggero ﷺ?", ["Duri con i miscredenti, misericordiosi tra loro", "Ricchi e numerosi", "Silenziosi e ritirati", "Viaggiatori e mercanti"], "«Muhammad è il Messaggero di Allah. E coloro che sono con lui sono duri con i miscredenti, misericordiosi tra loro»."),
"prophets_247": ("Che cosa dice la sura An-Najm della parola del Profeta ﷺ?", ["Non parla per passione: non è che una rivelazione ispirata", "Parla da poeta", "Parla da indovino", "Parla di suo"], "«Il vostro compagno non è traviato né si è sviato; e non parla per passione. Non è che una rivelazione ispirata»."),
"prophets_248": ("Che cosa fu ordinato al Profeta ﷺ quando giunse il soccorso di Allah e la vittoria?", ["Glorificare il suo Signore con la lode e chiederGli perdono", "Celebrare con un banchetto", "Erigere un monumento", "Riposare"], "«Quando giunge il soccorso di Allah e la vittoria… glorifica il tuo Signore con la lode e chiediGli perdono»."),
"prophets_249": ("Quali tre compiti attribuisce la sura Al-Jumu'a al Messaggero inviato agli illetterati?", ["Recitare i versetti, purificarli e insegnare loro il Libro e la saggezza", "Costruire, commerciare e governare", "Scrivere, contare e viaggiare", "Giudicare, punire e riscuotere"], "«Egli è colui che ha suscitato tra gli illetterati un Messaggero dei loro, che recita loro i Suoi versetti, li purifica e insegna loro il Libro e la saggezza»."),
"prophets_250": ("Quale salvaguardia menziona il Corano finché il Profeta ﷺ era tra loro?", ["Allah non li avrebbe castigati finché egli era tra loro", "Sarebbero stati ricchi", "Avrebbero sempre vinto", "Non sarebbero morti"], "«Ma Allah non li castigherà mentre tu sei tra loro»."),
}
